// components/Cart/Cart.js
import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { initCart, removeFromCart, updateItemDetails } from '../../actions/cartActions';
import CartItem from '../CartItem/CartItem';
import CartSummary from '../CartSummary/CartSummary';
import './CartMain.css';

const Cart = () => {
    const dispatch = useDispatch();
    const cart = useSelector((state) => state.cart);

    // Завантаження кошика з localStorage через Redux
    useEffect(() => {
        dispatch(initCart());
    }, [dispatch]);

    // Функція для оновлення кошика в localStorage
    const saveCartToLocalStorage = (newCart) => {
        localStorage.setItem('cart', JSON.stringify(newCart));
    };

    // Оновлення кошика після зміни
    const handleCartUpdate = (newCart) => {
        saveCartToLocalStorage(newCart);
        dispatch(initCart());  // Оновлюємо кошик у Redux
    };

    return (
        <div className="cart-page">
            <h1>Ваш кошик</h1>
            <div className="cart-items-list">
                {cart.length > 0 ? (
                    cart.map((item) => (
                        <CartItem key={item.id} item={item} onCartUpdate={handleCartUpdate} />
                    ))
                ) : (
                    <p className="cart-empty-message">Кошик порожній</p>
                )}
            </div>
            <CartSummary cart={cart} />
        </div>
    );
};

export default Cart;
